// ดึงข้อมูลจาก Item ปัจจุบัน
let item = $input.item.json;

// 1. แปลงชื่อขึ้นต้นด้วยตัวใหญ่ (Capitalize)
item.fullName = item.firstName.charAt(0).toUpperCase() + item.firstName.slice(1) + " " + 
                item.lastName.charAt(0).toUpperCase() + item.lastName.slice(1);

// 2. คำนวณอายุจากปีเกิด
let birthYear = parseInt(item.birthDate.split("/")[0]);
let currentYear = new Date().getFullYear();
item.age = currentYear - birthYear;

// ลบฟิลด์เก่าที่ไม่ใช้แล้ว
delete item.firstName;
delete item.lastName;

// ส่งข้อมูลกลับ
return item;
